//! `/etc/screentime/config.toml`, generated by the NixOS module.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail};
use serde::Deserialize;

use crate::Cutoff;
use crate::schedule::{DayRules, Schedule, parse_window};

pub const DEFAULT_PATH: &str = "/etc/screentime/config.toml";

/// Config path, overridable for testing.
pub fn path() -> PathBuf {
    std::env::var_os("SCREENTIME_CONFIG")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(DEFAULT_PATH))
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct RawConfig {
    #[serde(default = "default_idle")]
    idle_timeout_secs: u64,
    #[serde(default = "default_input_only")]
    input_idle_only: bool,
    #[serde(default = "default_heartbeat")]
    heartbeat_timeout_secs: u64,
    #[serde(default = "default_grace")]
    logout_grace_secs: u64,
    #[serde(default = "default_force")]
    force_logout_secs: u64,
    #[serde(default = "default_limit_action")]
    limit_action: TimeUpAction,
    #[serde(default = "default_window_end_action")]
    window_end_action: TimeUpAction,
    #[serde(default)]
    agent_path: Option<PathBuf>,
    #[serde(default)]
    users: BTreeMap<String, RawUser>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct RawUser {
    #[serde(default)]
    days: BTreeMap<String, RawDay>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct RawDay {
    #[serde(default)]
    windows: Vec<String>,
    #[serde(default)]
    limit_minutes: u64,
}

fn default_idle() -> u64 {
    300
}
fn default_input_only() -> bool {
    true
}
fn default_heartbeat() -> u64 {
    60
}
fn default_grace() -> u64 {
    30
}
fn default_force() -> u64 {
    20
}
fn default_limit_action() -> TimeUpAction {
    TimeUpAction::Logout
}
fn default_window_end_action() -> TimeUpAction {
    TimeUpAction::Shutdown
}

/// What happens once a user is out of time or outside their windows.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum TimeUpAction {
    /// Power the machine off.
    Shutdown,
    /// End the user's session; SDDM comes back.
    Logout,
    /// Lock the screen. The session stays open, but locked time isn't
    /// counted, and unlocking it gets it locked again.
    Lock,
}

#[derive(Debug, Clone)]
pub struct Config {
    /// No keyboard/mouse input for this long stops the counter.
    pub idle_timeout_secs: u64,
    /// Only real input counts as activity; idle inhibitors (video players,
    /// games) don't keep the counter running.
    pub input_idle_only: bool,
    /// No heartbeat from the agent for this long: assume active (fail closed).
    pub heartbeat_timeout_secs: u64,
    /// Time between running out and the agent's clean Plasma logout,
    /// shutdown or screen lock.
    pub logout_grace_secs: u64,
    /// If that didn't happen this long after the grace period (agent killed,
    /// logout cancelled), the daemon does it through logind.
    pub force_logout_secs: u64,
    /// When today's minutes run out (or the admin ends the day).
    pub limit_action: TimeUpAction,
    /// When the allowed window ends.
    pub window_end_action: TimeUpAction,
    /// Heartbeats are only accepted from a process running this executable.
    pub agent_path: Option<PathBuf>,
    pub users: BTreeMap<String, Schedule>,
}

const DAYS: [&str; 7] = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"];

impl Config {
    /// The action for whatever ended the user's time.
    pub fn action(&self, cutoff: Cutoff) -> TimeUpAction {
        match cutoff {
            Cutoff::Limit => self.limit_action,
            Cutoff::Window => self.window_end_action,
        }
    }

    pub fn load(path: &Path) -> Result<Self> {
        let text =
            std::fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
        Self::parse(&text).with_context(|| format!("parsing {}", path.display()))
    }

    pub fn parse(text: &str) -> Result<Self> {
        let raw: RawConfig = toml::from_str(text)?;
        let mut users = BTreeMap::new();
        for (name, user) in raw.users {
            let mut days: [DayRules; 7] = Default::default();
            for (day, rules) in user.days {
                let Some(idx) = DAYS.iter().position(|d| *d == day) else {
                    bail!("user {name}: unknown day {day:?} (expected one of {DAYS:?})");
                };
                let windows = rules
                    .windows
                    .iter()
                    .map(|w| parse_window(w))
                    .collect::<Result<Vec<_>>>()
                    .with_context(|| format!("user {name}, {day}"))?;
                days[idx] = DayRules::new(windows, rules.limit_minutes * 60)
                    .with_context(|| format!("user {name}, {day}"))?;
            }
            users.insert(name, Schedule { days });
        }
        Ok(Config {
            idle_timeout_secs: raw.idle_timeout_secs,
            input_idle_only: raw.input_idle_only,
            heartbeat_timeout_secs: raw.heartbeat_timeout_secs,
            logout_grace_secs: raw.logout_grace_secs,
            force_logout_secs: raw.force_logout_secs,
            limit_action: raw.limit_action,
            window_end_action: raw.window_end_action,
            agent_path: raw.agent_path,
            users,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_full_config() {
        let cfg = Config::parse(
            r#"
            idle_timeout_secs = 300
            agent_path = "/nix/store/x/bin/screentime-agent"
            [users.benny.days.mon]
            windows = ["15:00-20:00"]
            limit_minutes = 90
            [users.benny.days.sat]
            windows = ["09:00-12:00", "14:00-21:00"]
            limit_minutes = 180
            "#,
        )
        .unwrap();
        let s = &cfg.users["benny"];
        assert_eq!(s.days[0].limit_secs, 90 * 60);
        assert_eq!(s.days[5].windows.len(), 2);
        assert!(s.days[1].windows.is_empty());
        assert!(cfg.input_idle_only);
        assert_eq!(cfg.action(Cutoff::Limit), TimeUpAction::Logout);
        assert_eq!(cfg.action(Cutoff::Window), TimeUpAction::Shutdown);
    }

    #[test]
    fn parses_actions() {
        let cfg = Config::parse("limit_action = \"lock\"\nwindow_end_action = \"logout\"").unwrap();
        assert_eq!(cfg.action(Cutoff::Limit), TimeUpAction::Lock);
        assert_eq!(cfg.action(Cutoff::Window), TimeUpAction::Logout);
        assert!(Config::parse("limit_action = \"reboot\"").is_err());
    }

    #[test]
    fn rejects_bad_day() {
        let err = Config::parse("[users.benny.days.funday]\nlimit_minutes = 1").unwrap_err();
        assert!(format!("{err:#}").contains("unknown day"));
    }

    #[test]
    fn rejects_overlap() {
        let err = Config::parse(
            "[users.b.days.mon]\nwindows = [\"09:00-12:00\", \"11:00-13:00\"]\nlimit_minutes = 60",
        )
        .unwrap_err();
        assert!(format!("{err:#}").contains("overlap"));
    }
}
